package com.taller.gestion.controller;
import com.taller.gestion.domain.*; import com.taller.gestion.repository.WorkOrderRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/orders") @CrossOrigin(origins="*") public class WorkOrderController { private final WorkOrderRepository repo; public WorkOrderController(WorkOrderRepository repo){this.repo=repo;} @GetMapping public List<WorkOrder> all(){return repo.findAll();} @PostMapping public ResponseEntity<WorkOrder> create(@Valid @RequestBody NewOrder body){WorkOrder o=new WorkOrder();o.setFolio("OT-"+System.currentTimeMillis());o.setClientName(body.clientName());o.setClientPhone(body.clientPhone());o.setVehicle(body.vehicle());o.setPlates(body.plates());o.setReportedProblem(body.reportedProblem());o.setInitialCondition(body.initialCondition());return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(o));} @PatchMapping("/{id}/quote") public WorkOrder quote(@PathVariable Long id,@RequestBody Quote b){WorkOrder o=repo.findById(id).orElseThrow();o.setQuotedTotal(b.total());o.setPromisedDeliveryAt(b.deliveryAt());return repo.save(o);} @PatchMapping("/{id}/feedback") public WorkOrder feedback(@PathVariable Long id,@RequestBody Feedback b){WorkOrder o=repo.findById(id).orElseThrow();o.setCustomerFeedback(b.comment());return repo.save(o);} public record NewOrder(@NotBlank String clientName,String clientPhone,@NotBlank String vehicle,@NotBlank String plates,@NotBlank String reportedProblem,String initialCondition){} public record Quote(BigDecimal total,LocalDateTime deliveryAt){} public record Feedback(String comment){} }
